{
  "title": "The Glass Diver's Rescue",
  "scenes": [
    {
      "scene_number": 1,
      "caption": "A map is unrolled at the edge of the ruined city.",
      "visual_description": "On a windy hill above broken spires, an ink-stained coat flaps as a brass compass pins down a torn map of the fallen capital.",
      "characters": ["mara_the_cartographer"]
    },
    {
      "scene_number": 2,
      "caption": "The lamp wakes with a warning.",
      "visual_description": "A battered oil lamp set on a stone marker flickers open a single eye in its flame, casting long shadows across cracked cobblestones.",
      "characters": ["mara_the_cartographer", "oracle_lamp"]
    },
    {
      "scene_number": 3,
      "caption": "A clockwork scout is wound up for the mission.",
      "visual_description": "A small tin fox with blue glass eyes stands on the map while a gloved hand twists the key in its tail; gears tick under moonlight.",
      "characters": ["mara_the_cartographer", "tin_fox"]
    },
    {
      "scene_number": 4,
      "caption": "The glass diver emerges from a puddle of moonlight.",
      "visual_description": "A figure in a clear diving helmet rises from a rain-puddle reflection, coat shimmering with the broken neon of fallen banners.",
      "characters": ["glass_diver", "mara_the_cartographer"]
    },
    {
      "scene_number": 5,
      "caption": "The team approaches the shattered castle gates.",
      "visual_description": "Two enormous iron gates hang twisted off their hinges; the tin fox darts ahead while the lamp's eye throws a warning glow on the threshold.",
      "characters": ["mara_the_cartographer", "tin_fox", "oracle_lamp", "glass_diver"]
    },
    {
      "scene_number": 6,
      "caption": "A cursed tower leans over the avenue.",
      "visual_description": "A black tower tilts above the street, its windows weeping green smoke; the lamp's eye narrows as Mara points to a side alley on her map.",
      "characters": ["mara_the_cartographer", "oracle_lamp"]
    },
    {
      "scene_number": 7,
      "caption": "Rumors of a great beast rattle loose tiles.",
      "visual_description": "Scaled shadows ripple across a courtyard wall; the tin fox crouches low, blue eyes wide, as distant wingbeats shake roof tiles into the gutter.",
      "characters": ["tin_fox", "glass_diver"]
    },
    {
      "scene_number": 8,
      "caption": "Torn royal banners hang like nooses across the square.",
      "visual_description": "Faded gold-and-crimson banners drape between broken pillars; Mara pushes through them with her compass raised, ignoring the temptation to climb the dais.",
      "characters": ["mara_the_cartographer"]
    },
    {
      "scene_number": 9,
      "caption": "Frightened faces peer from boarded windows.",
      "visual_description": "Pale eyes glint from slits in shuttered houses; the glass diver presses a gloved hand to a windowpane, his reflection swimming inside the glass.",
      "characters": ["glass_diver"]
    },
    {
      "scene_number": 10,
      "caption": "An armored patrol marches the boulevard.",
      "visual_description": "Rows of empty steel helms clank past in lockstep down a fog-filled avenue; the tin fox flattens beneath a tipped cart, gears silenced.",
      "characters": ["tin_fox", "oracle_lamp"]
    },
    {
      "scene_number": 11,
      "caption": "They find the sleeping official at his desk.",
      "visual_description": "Inside a ransacked toll house, a portly man snores on a ledger pillow, stamped papers stuck to his sleeves, oblivious to the chaos outside.",
      "characters": ["sleeping_tax_collector", "mara_the_cartographer"]
    },
    {
      "scene_number": 12,
      "caption": "The lamp demands they wake the dozing clerk.",
      "visual_description": "The oracle lamp's flame-eye flares above the desk; the sleeping tax collector mumbles and rolls over, drooling onto a wax seal.",
      "characters": ["oracle_lamp", "sleeping_tax_collector", "mara_the_cartographer"]
    },
    {
      "scene_number": 13,
      "caption": "A magic door blocks the inner keep.",
      "visual_description": "An obsidian door pulses with silver runes at the end of a vaulted hall; the glass diver presses his helmet to its mirrored surface, listening.",
      "characters": ["glass_diver", "oracle_lamp"]
    },
    {
      "scene_number": 14,
      "caption": "The diver slips through the mirror-door.",
      "visual_description": "The rescuer dives headfirst into the rune-lit obsidian as if into water; ripples spread across the door while the tin fox watches, ears perked.",
      "characters": ["glass_diver", "tin_fox"]
    },
    {
      "scene_number": 15,
      "caption": "He emerges in the captive's mirrored cell.",
      "visual_description": "Inside a glass-walled chamber, the diver climbs out of a tall standing mirror, coat dripping reflected starlight onto a chained, sleeping figure.",
      "characters": ["glass_diver", "sleeping_tax_collector"]
    },
    {
      "scene_number": 16,
      "caption": "The rescue spills back into the courtyard.",
      "visual_description": "Mara waves frantically from a broken archway, compass spinning wild, as the diver hauls the snoring official across the rubble with the fox in tow.",
      "characters": ["mara_the_cartographer", "glass_diver", "sleeping_tax_collector", "tin_fox"]
    },
    {
      "scene_number": 17,
      "caption": "They race for the long bridge out of the city.",
      "visual_description": "A narrow stone bridge arches over a black river, lit by the lamp's eye; behind them, the cursed tower finally collapses in a plume of green sparks.",
      "characters": ["mara_the_cartographer", "glass_diver", "oracle_lamp", "sleeping_tax_collector", "tin_fox"]
    },
    {
      "scene_number": 18,
      "caption": "Safe on the far shore, the map is rolled away.",
      "visual_description": "Dawn breaks over the river; Mara tucks the map under her arm, the tin fox curls at her boots, the lamp dims to a candle's glow, and the diver gazes back at the ruined skyline.",
      "characters": ["mara_the_cartographer", "glass_diver", "tin_fox", "oracle_lamp", "sleeping_tax_collector"]
    }
  ]
}

